const row = $input.first().json;
const stamp = new Date().toISOString().replace(/[-:T]/g,'').slice(0,15);
const filename = 'arquitai_backup_' + stamp + '.json.enc';
const encryptedBuffer = Buffer.from(row.encrypted_b64, 'base64');
const snapshot = row.snapshot;
const tablesSummary = {};
for (const k of Object.keys(snapshot)) {
  if (k === 'metadata') continue;
  tablesSummary[k] = Array.isArray(snapshot[k]) ? snapshot[k].length : 0;
}
return [{
  json: {
    filename,
    plaintextSizeBytes: row.plaintext_size_bytes,
    encryptedSizeBytes: row.encrypted_size_bytes,
    tablesSummary,
    encrypted: true,
    started_at: Date.now()
  },
  binary: {
    data: {
      data: encryptedBuffer.toString('base64'),
      mimeType: 'application/octet-stream',
      fileName: filename
    }
  }
}];

