INSERT INTO system_backups (backup_type, drive_file_id, drive_url, size_bytes, status, started_at, finished_at)
VALUES ('table_export', $1, $2, $3::bigint, 'success', to_timestamp($4::numeric / 1000.0), now())
RETURNING id;

INSERT INTO system_backups (backup_type, status, size_bytes, started_at, finished_at, error_message)
VALUES ('table_export', 'failed', $1::bigint, to_timestamp($2::numeric / 1000.0), now(), $3)
RETURNING id;
